### Setting a Cookie
```javascript
function setCookie(name, value, days) {
    var expires = "";
    if (days) {
        var date = new Date();
        date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
        expires = "; expires=" + date.toUTCString();
    }
    document.cookie = name + "=" + (value || "") + expires + "; path=/";
}
```

### Getting a Cookie
```javascript
function getCookie(name) {
    var nameEQ = name + "=";
    var ca = document.cookie.split(';');
    for (var i = 0; i < ca.length; i++) {
        var c = ca[i];
        while (c.charAt(0) == ' ') c = c.substring(1, c.length);
        if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
    }
    return null;
}
```

### Checking if a Cookie Exists
```javascript
function checkCookie(name) {
    var value = getCookie(name);
    if (value != null) {
        return true;
    } else {
        return false;
    }
}
```

### Example Usage
```javascript
// Set a cookie
setCookie("username", "JohnDoe", 7); // This will set a cookie named "username" with value "JohnDoe" that expires in 7 days.

// Get a cookie
var username = getCookie("username");
console.log("Username: " + username); // Output: Username: JohnDoe

// Check if a cookie exists
var cookieExists = checkCookie("username");
console.log("Cookie exists: " + cookieExists); // Output: Cookie exists: true
```

